extern uint8_t IRQH_IRQ[8];  /* P42-DIAG: irqh.c defined, no header decl */
/* P483: Mercury Unit の配線確定値(EmulatorBridge.c 定義)。
 * 0 = 未装着 → $ECC000-$ECDFFF は従来どおり全域バスエラー(P221d の忠実性)。
 * 1 = 装着   → レジスタ範囲のみ疎通させる(§変更 3)。 */
extern int g_mercury_installed;
/* P506 (D-28): 外付け SCSI ボード(CZ-6BS1 等)の配線確定値(EmulatorBridge.c 定義)。
 * 0 = 未装着 → $EA0000-$EA1FFF はバスエラー(XM6 vm/scsi.cpp:568-583 相当)。
 * 1 = 装着   → 従来どおり Core の SCSI_Read/SCSI_Write へ素通しする。 */
extern int g_scsi_ext_board_wired;

/* P483b: 装着時に疎通させるレジスタ範囲の境界。
 * MCRY_REG_BASE — V4/MK-MU10 完全レジスタセットの下限。$ECC0B1(割込ベクタ)・
 *   $ECC0C1-C7(OPN)が $ECC080 側にしか存在しない(Core/px68k/x68k/mercury.c の
 *   Mcry_Write/Mcry_Read 直読)ことから、完全なレジスタセットは $ECC080 ベース。
 *   これは参照実装に合わせた変更ではなく「MX が V4/MK-MU10 相当を名乗る」という
 *   MX 固有の設計判断(本家 px68k の Mcry_Write は $ECC000/001 も実際に
 *   マッチさせて処理する)。
 * MCRY_REG_END  — 疎通範囲の上限(P483 で確定済み、本家 mercury.c の
 *   `else if (adr>=0xecc100) BusErrFlag=1` に由来)。 */
#define MCRY_REG_BASE 0x00ECC080u
#define MCRY_REG_END  0x00ECC0FFu

/* P252 Stage 2c-2: internal SCSI (SPC) level-1 interrupt pending state.
 * Default is fully inert (g_spc_pending stays 0) — nothing sets it until the
 * guest raises the SPC enable bit and the SCSI class calls
 * cpu->Interrupt(1,...). Cleared on hard reset via mx68k_scsi_irq_reset().
 * The multiplexer that consumes this lives in mx68k_diag_irqh_callback(). */
static int     g_spc_pending = 0;
static int32_t g_spc_vec     = -1;

/* ACK delegation into the ported SCSI class (scsi_spc_bridge.cpp). */
extern void scsi_real_int_ack(int level);
/* Defined later in this TU (~line 29777); no header decl, so forward it. */
void m68000_set_irq_line(int32_t irqline);

/* ====================================================================
 *  P510 (D-32) 診断プローブ [P510-EXTIRQ] — 条件付き発火(呼出しがあった時のみ)
 *
 *  移植済み SPC が cpu->Interrupt(level, vector) を呼んだ事実を、レベルに
 *  関わらず**ガードより手前で**記録する。外付け CZ-6BS1 はレベル 2(既定、
 *  scsi_spc.cpp:95 の scsi.ilevel=2)・ベクタ $F6(scsi_spc.cpp:2572)で
 *  要求するため、既存の `level != 1` ガードに落ちて痕跡が残らなかった。
 *  本サイクルでは実際の割込み配線は行わず(ガードは無変更で維持)、
 *  「レベル 2 の要求が来ているか」だけを観測する。
 *
 *  自己反証可能性: 本ログは条件付き発火なので、これ単独では「0 件」を
 *  「要求が無かった」と「そもそも SPC が動いていない」に切り分けられない。
 *  分母は無条件発火の [P510-SCTL](p510_ext_scsi_dump)が持ち、そちらへ
 *  irq_count を複写するので、1 行だけで判別できる。
 *  カウンタ g_p510_irq_count は上限なしで数え続け、印字だけを上限で抑える
 *  (分母の正確さを保ったままログ肥大を防ぐ)。
 * ==================================================================== */
static uint32_t g_p510_irq_count = 0;
static uint32_t g_p510_irq_logged = 0;
#define P510_EXTIRQ_LOG_MAX 500

void mx68k_scsi_irq_raise(int level, int vector) {
    g_p510_irq_count++;
    if (g_p510_irq_logged < P510_EXTIRQ_LOG_MAX) {
        g_p510_irq_logged++;
        debug_log("[P510-EXTIRQ] level=%d vec=0x%02x n=%u\n",
                  level, (unsigned)(vector & 0xff), g_p510_irq_count);
        if (g_p510_irq_logged == P510_EXTIRQ_LOG_MAX) {
            debug_log("[P510-EXTIRQ] log cap reached (%d) — counting continues, printing suppressed\n",
                      P510_EXTIRQ_LOG_MAX);
        }
    }
    if (level != 1) return;   /* internal SCSI is level-1 only (scsi_spc.cpp) */
    g_spc_pending = 1;
    g_spc_vec = vector;
    m68000_set_irq_line(1);
}

void mx68k_scsi_irq_cancel(int level) {
    if (level != 1) return;
    g_spc_pending = 0;
    /* Do not force the level-1 line low here: IRQH_IRQ[1] may still hold a
     * pending Core device (FDC/FDD/SASI). Leaving the line as-is preserves
     * their delivery; the multiplexer re-evaluates on the next IACK. */
}

void mx68k_scsi_irq_reset(void) {   /* called from mx68k_reset_hard (§2-4) */
    g_spc_pending = 0;
    g_spc_vec = -1;
}

