static uint32_t p214_r2_line_count(const p214_bucket_t *p) {
    uint32_t c = 0;
    for (int i = 0; i < 32; i++) c += (uint32_t)__builtin_popcount(p->lines[i]);
    return c;
}

/* EmulatorBridge.c の mx68k_render_frame() が毎フレーム 1 回呼ぶ（出力は 60 フレームに 1 回）。
 * 整形してから累積をクリアする = R1 と同じ per-frame 意味論。 */
void p214_r2_format_and_reset(char *buf, int len) {
    static const char *names[P214_NBUCKET] = { "PAL", "VC", "CSC", "CRT", "BGR" };
    if (!buf || len <= 0) return;
    buf[0] = '\0';
    int off = 0;
    for (int i = 0; i < P214_NBUCKET; i++) {
        int w = snprintf(buf + off, (size_t)(len - off),
                         "%s n=%u lines=%u disp=%u ",
                         names[i], s_p214_bk[i].n,
                         p214_r2_line_count(&s_p214_bk[i]), s_p214_bk[i].disp);
        if (w < 0) break;
        off += w;
        if (off >= len - 1) break;   /* 切り詰め: snprintf が NUL 終端済み */
    }
    buf[len - 1] = '\0';
    memset(s_p214_bk, 0, sizeof(s_p214_bk));
}
#endif /* P214_ENABLE */

