    s_p82q_prev_ipra = s_p82q_prev_iprb = 0;
    s_p82q_prev_imra = s_p82q_prev_imrb = 0;
    s_p82q_prev_isra = s_p82q_prev_isrb = 0;
    s_p82q_prev_vr   = 0;
    s_p82q_prev_mfp_valid = 0;
    s_p82q_prev_irqline   = 0;
    s_p82q_prev_iplmask   = 0;
    s_p82q_prev_irqh6     = 0;
    s_p82q_prev_cpu_valid = 0;
    s_p82q_isr_prev_in_band = 0;
    s_p82q_isr_prev_band_id = 0;
    s_p82q_isr_pending_enter_pc   = 0;
    s_p82q_isr_pending_enter_a7   = 0;
    s_p82q_isr_pending_enter_iprb = 0;
    s_p82q_isr_pending_enter_isrb = 0;
